import sys

def solve_fillomino(n, p):
    # Initialize the grid with -1
    grid = [[-1] * n for _ in range(n)]

    # Place the numbers on the main diagonal
    for i in range(n):
        grid[i][i] = p[i]

    # Try to fill the regions
    for i in range(n):
        region_size = p[i]
        queue = [(i, i)]
        visited = set(queue)

        while queue:
            x, y = queue.pop(0)

            # Check if we have filled the current region
            if sum(row.count(p[i]) for row in grid) == region_size:
                break

            # Try to add adjacent cells to the region
            for dx, dy in [(-1, 0), (0, -1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == -1:
                    grid[nx][ny] = p[i]
                    queue.append((nx, ny))
                    visited.add((nx, ny))

        # If we couldn't fill the region, return -1
        if sum(row.count(p[i]) for row in grid) != region_size:
            return -1

    # Prepare the output
    result = []
    for i in range(n):
        row = []
        for j in range(i + 1):
            row.append(grid[i][j])
        result.append(row)

    return result

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    p = list(map(int, input[1:]))

    result = solve_fillomino(n, p)

    if result == -1:
        print(-1)
    else:
        for row in result:
            print(" ".join(map(str, row)))

if __name__ == "__main__":
    main()
